const input = $input.first()?.json ?? {};

const action = input.action ?? null;
const params = input.params ?? {};
const session_id = input.session_id ?? null;
const message = input.message ?? "";

if (!action) {
  throw new Error("Missing action");
}

if (!session_id) {
  throw new Error("Missing session_id");
}

if (!params || typeof params !== "object") {
  throw new Error("Missing params object");
}

if (!params.usecase_name) {
  throw new Error("Missing params.usecase_name");
}

return [{
  json: {
    action,
    params,
    session_id,
    message
  }
}];

const original = $('Validate Builder Input').first().json;

// Get all rows from the dictionary query.
const dictionaryRows = $input.all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0 && row.usecase_parameter_name);

const dictionary_parameters = dictionaryRows.map(row => ({
  name: row.usecase_parameter_name,
  format: row.parameter_format,
  required: Boolean(row.is_required),
  description: row.description ?? ""
}));

const warnings = [];

if (dictionary_parameters.length === 0) {
  warnings.push(
    `No parameters were found in UseCaseDictionary for use case "${original.params.usecase_name}". The AI can still generate generic snippets, but the researcher should verify the required input parameters.`
  );
}

return [{
  json: {
    action: original.action,
    params: original.params,
    dictionary_parameters,
    session_id: original.session_id,
    message: original.message,
    warnings
  }
}];

const ctx = $input.first().json;

const params = ctx.params ?? {};
const dictionary = ctx.dictionary_parameters ?? [];
const warnings = ctx.warnings ?? [];

const apiMetadata = {
  api_name: params.api_name ?? params.usecase_name ?? "",
  usecase_name: params.usecase_name ?? "",
  endpoint_url: null,
  required_query_parameters: [],
  response_value_path: params.response_value_path ?? "",
  measurement_name: params.measurement_name ?? "",
  context: params.context ?? ""
};

// Try to detect endpoint URL from dictionary parameter named "url"
const urlParam = dictionary.find(p =>
  String(p.name).toLowerCase() === "url"
);

if (urlParam?.description) {
  const match = String(urlParam.description).match(/https?:\/\/[^\s]+/);
  if (match) {
    apiMetadata.endpoint_url = match[0];
  }
}

// Treat all non-url dictionary parameters as API/request parameters
apiMetadata.required_query_parameters = dictionary
  .filter(p => String(p.name).toLowerCase() !== "url")
  .map(p => ({
    name: p.name,
    format: p.format,
    required: p.required,
    description: p.description
  }));

if (!apiMetadata.endpoint_url) {
  warnings.push(
    `No API endpoint URL was detected for "${apiMetadata.usecase_name}". The AI should ask the researcher to verify the endpoint if needed.`
  );
}

if (!apiMetadata.response_value_path) {
  warnings.push(
    `No response_value_path was provided for "${apiMetadata.usecase_name}". The researcher must provide the JSON path of the numeric value inside the API response.`
  );
}

return [{
  json: {
    ...ctx,
    api_metadata: apiMetadata,
    warnings
  }
}];

const input = $input.first().json;

const raw =
  input.text ??
  input.output ??
  input.response ??
  input.result ??
  "";

const cleaned = String(raw)
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "Use Case Builder AI did not return valid JSON. Raw output was: " + cleaned
  );
}

if (!parsed.usecase_name) {
  throw new Error("AI output is missing usecase_name");
}

if (!parsed.summary) {
  parsed.summary = "";
}

if (!Array.isArray(parsed.nodes)) {
  throw new Error("AI output is missing nodes array");
}

const requiredNodeKeys = [
  "WEBHOOK_NODE",
  "SET_TYPE_NODE",
  "NORMALIZE_INPUT_NODE",
  "CONSTRUCT_API_REQUEST_NODE",
  "HTTP_REQUEST_NODE",
  "EXTRACT_MEASUREMENT_NODE",
  "FETCH_RULES_SQL_NODE",
  "EVALUATE_HAPTICS_NODE",
  "RESPOND_SUCCESS_NODE",
  "BUILD_INSERT_SENSOR_DATA_NODE",
  "RATE_LIMITED_RESPONSE_NODE",
  "TEST_CURL_COMMAND"
];

const foundNodeKeys = parsed.nodes.map(node => node.node_key);

const missingNodeKeys = requiredNodeKeys.filter(
  key => !foundNodeKeys.includes(key)
);

if (!Array.isArray(parsed.required_researcher_checks)) {
  parsed.required_researcher_checks = [];
}

if (!Array.isArray(parsed.warnings)) {
  parsed.warnings = [];
}

if (missingNodeKeys.length > 0) {
  parsed.warnings.push(
    `Missing generated sections: ${missingNodeKeys.join(", ")}`
  );
}

return [{
  json: {
    ...parsed,
    session_id: $("Build Builder Prompt").first().json.session_id
  }
}];

const data = $input.first().json;

function formatGeneratedContent(content) {
  if (typeof content === "string") {
    return content;
  }

  return JSON.stringify(content, null, 2);
}

let reply = `🧩 Use Case Builder output for **${data.usecase_name}**\n\n`;

if (data.summary) {
  reply += `${data.summary}\n\n`;
}

reply += `## Node changes to apply\n\n`;

for (const node of data.nodes ?? []) {
  reply += `### ${node.node_key}\n`;
  reply += `**Node hint:** ${node.node_name_hint ?? ""}\n`;
  reply += `**Field to change:** ${node.field_to_change ?? ""}\n\n`;
  reply += "```text\n";
  reply += formatGeneratedContent(node.generated_content);
  reply += "\n```\n";

  if (node.explanation) {
    reply += `${node.explanation}\n`;
  }

  reply += "\n";
}

if (
  Array.isArray(data.required_researcher_checks) &&
  data.required_researcher_checks.length > 0
) {
  reply += `## Researcher checks before running\n`;

  for (const check of data.required_researcher_checks) {
    reply += `- ${check}\n`;
  }

  reply += "\n";
}

if (Array.isArray(data.warnings) && data.warnings.length > 0) {
  reply += `## Warnings\n`;

  for (const warning of data.warnings) {
    reply += `- ${warning}\n`;
  }

  reply += "\n";
}

return [{
  json: {
    reply,
    session_id: data.session_id
  }
}];
